<script setup lang="ts">
import type { ApiSuccess } from '~/types/api'
definePageMeta({layout:'dashboard',middleware:'auth'});useHead({title:'Facturation'})
type Billing={id:string;kind:string;number:string;status:string;issueDate:string;dueDate:string|null;currency:string;subject:string|null;subtotal:string;taxAmount:string;total:string;client:{id:string;name:string};project:{id:string;reference:string|null;title:string}|null;_count:{lines:number}}
const {data,error,refresh}=await useFetch<ApiSuccess<Billing[]>>('/api/billing');const docs=computed(()=>data.value?.data??[]);const money=(v:string,c:string)=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:c}).format(Number(v));const date=(v:string|null)=>v?new Date(v).toLocaleDateString('fr-FR'):'—'
</script>
<template><div><div class="page-head"><div><h1>Facturation</h1><p>Devis, factures et suivi des règlements.</p></div><button class="btn btn-secondary" type="button" @click="refresh()">Actualiser</button></div><div v-if="error" class="alert alert-error">Impossible de charger la facturation.</div><div v-else-if="!docs.length" class="empty-state">Aucun document de facturation.</div><div v-else class="table-wrap"><table><thead><tr><th>Numéro</th><th>Client</th><th>Date</th><th>Échéance</th><th>Total</th><th>Statut</th></tr></thead><tbody><tr v-for="doc in docs" :key="doc.id"><td><strong>{{ doc.number }}</strong><br><small>{{ doc.kind }}</small></td><td>{{ doc.client.name }}</td><td>{{ date(doc.issueDate) }}</td><td>{{ date(doc.dueDate) }}</td><td>{{ money(doc.total,doc.currency) }}</td><td><span class="badge">{{ doc.status }}</span></td></tr></tbody></table></div></div></template>
